B.b65=new A.bn(9,"odjede","sfx_story_truck_leave",null,1)
B.b6s=new A.bn(9,"tik\xe1n\xed","sfx_story_soft_ticking",null,1)
B.a7O=s([B.b6p,B.b6b,B.b65,B.b6s],t.c)
B.aHF=new A.h(0,0,170.20355132091814,311.82330012992634)
B.aIc=new A.h(120,0,311.85794716327416,170.20355132091814)
B.aFs=new A.h(129.9,129.9,311.79692507579034,311.79692507579034)
B.iZ=s([B.aHF,B.aIc,B.aFs],t.u)
B.ah9=new A.b2("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.c5=new A.lW("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a2B=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.aUj=new A.a8(B.c5,B.a2B,!1)
B.bf=new A.lW("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.a5X=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.aWf=new A.a8(B.bf,B.a5X,!1)
B.aa8=s([B.ah9,B.aUj,B.aWf],t.a)
B.aXf=new A.cy("story_00_intro",B.aa8)
B.agD=new A.b2("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.a3i=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.aUr=new A.a8(B.c5,B.a3i,!1)
B.ahg=new A.b2("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.a3r=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.aUn=new A.a8(B.bf,B.a3r,!1)
B.cc=new A.lW("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.ab6=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.aW4=new A.a8(B.cc,B.ab6,!1)
B.a3D=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.aVw=new A.a8(B.c5,B.a3D,!1)
B.aai=s([B.agD,B.aUr,B.ahg,B.aUn,B.aW4,B.aVw],t.a)
B.aWY=new A.cy("story_01a_clubhouse_arrival",B.aai)
B.a4H=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.aUW=new A.a8(B.c5,B.a4H,!1)
B.a6h=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.aVA=new A.a8(B.cc,B.a6h,!1)
B.a1G=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.aVS=new A.a8(B.bf,B.a1G,!1)
B.a3n=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.aVP=new A.a8(B.cc,B.a3n,!1)
B.a2D=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.aV8=new A.a8(B.bf,B.a2D,!1)
B.a0D=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.aU6=new A.a8(B.c5,B.a0D,!1)
B.a8n=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.aWj=new A.a8(B.bf,B.a8n,!1)
B.ach=s([B.aUW,B.aVA,B.aVS,B.aVP,B.aV8,B.aU6,B.aWj],t.a)
B.aWT=new A.cy("story_01b_legend_and_time",B.ach)
B.ahH=new A.b2("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.a4L=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.aV2=new A.a8(B.bf,B.a4L,!1)
B.a49=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.aWs=new A.a8(B.cc,B.a49,!1)
B.abM=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.aVO=new A.a8(B.bf,B.abM,!1)
B.a8_=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.aU1=new A.a8(B.cc,B.a8_,!1)
B.a2p=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.aU4=new A.a8(B.c5,B.a2p,!1)
B.a6M=s([B.ahH,B.aV2,B.aWs,B.aVO,B.aU1,B.aU4],t.a)
B.aWS=new A.cy("story_02_torn_map",B.a6M)
B.a1H=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.aV1=new A.a8(B.c5,B.a1H,!1)
B.a8O=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.aW9=new A.a8(B.bf,B.a8O,!1)
B.agX=new A.b2("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.aba=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.aWa=new A.a8(B.cc,B.aba,!1)
B.abp=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.aWd=new A.a8(B.bf,B.abp,!1)
B.a7x=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.aUp=new A.a8(B.c5,B.a7x,!1)
B.a22=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.aUU=new A.a8(B.bf,B.a22,!1)
B.a27=s([B.aV1,B.aW9,B.agX,B.aWa,B.aWd,B.aUp,B.aUU],t.a)
B.aWU=new A.cy("story_03_founders_trail",B.a27)
B.agF=new A.b2("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.a3O=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.aWn=new A.a8(B.bf,B.a3O,!1)
B.a8i=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.aVJ=new A.a8(B.cc,B.a8i,!1)
B.aaR=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.aVT=new A.a8(B.bf,B.aaR,!1)
B.a51=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.aVB=new A.a8(B.c5,B.a51,!1)
B.a1f=s([B.agF,B.aWn,B.aVJ,B.aVT,B.aVB],t.a)
B.aWQ=new A.cy("story_04_flowers_in_mud",B.a1f)
B.ah1=new A.b2("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.a31=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.aUy=new A.a8(B.bf,B.a31,!1)
B.a0I=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.aVv=new A.a8(B.cc,B.a0I,!1)
B.a5x=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.aWw=new A.a8(B.bf,B.a5x,!1)
B.acq=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.aUT=new A.a8(B.c5,B.acq,!1)
B.a7U=s([B.ah1,B.aUy,B.aVv,B.aWw,B.aUT],t.a)
B.aXp=new A.cy("story_05_old_oak",B.a7U)
B.agY=new A.b2("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.a8T=s(["\u201eCo se to stalo?\u201c"],t.s)
B.aWe=new A.a8(B.bf,B.a8T,!1)
B.a5n=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.aUR=new A.a8(B.c5,B.a5n,!1)
B.a39=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.aUP=new A.a8(B.bf,B.a39,!1)
B.a5Z=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.aVE=new A.a8(B.c5,B.a5Z,!1)
B.agK=new A.b2("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.a5A=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.aVs=new A.a8(B.cc,B.a5A,!1)
B.ac7=s([B.agY,B.aWe,B.aUR,B.aUP,B.aVE,B.agK,B.aVs],t.a)
B.aWV=new A.cy("story_06_waterfall_chest",B.ac7)
B.ahf=new A.b2("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.a4c=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.aWy=new A.a8(B.cc,B.a4c,!1)
B.ac3=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.aUS=new A.a8(B.c5,B.ac3,!1)
B.ahy=new A.b2("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.acf=s([B.ahf,B.aWy,B.aUS,B.ahy],t.a)
B.aXa=new A.cy("story_07_scroll",B.acf)
B.agv=new A.b2("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aaG=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.aWo=new A.a8(B.bf,B.aaG,!1)
B.a9o=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.aTU=new A.a8(B.cc,B.a9o,!1)
B.a3k=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.aTZ=new A.a8(B.bf,B.a3k,!1)
B.a6y=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.aUz=new A.a8(B.cc,B.a6y,!1)
B.a7m=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.aWb=new A.a8(B.c5,B.a7m,!1)
B.a7V=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.aTR=new A.a8(B.cc,B.a7V,!1)
B.a7Q=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.aUB=new A.a8(B.bf,B.a7Q,!1)
B.a5y=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.aVi=new A.a8(B.cc,B.a5y,!1)
B.a2A=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.aUm=new A.a8(B.c5,B.a2A,!1)
B.a2h=s([B.agv,B.aWo,B.aTU,B.aTZ,B.aUz,B.aWb,B.aTR,B.aUB,B.aVi,B.aUm],t.a)
B.aX0=new A.cy("story_08_ending_dialogue",B.a2h)
